'use client'

/**
 * Table schema designer.
 *
 * Replaces the old NewTableModal, which had no way to remove a column, no
 * primary-key control (the backend accepted one and the UI never sent it), no
 * per-column validation, and a single error banner that could not say which
 * field was wrong.
 *
 * The SQL preview is generated by the same builder the server uses
 * (`lib/schema.ts` mirrors `backend/core/schema_rules.py`), so what the user
 * reads here is the statement that will actually run.
 */

import { useCallback, useMemo, useState } from 'react'
import { AlertCircle, ArrowDown, ArrowUp, Plus, Trash2 } from 'lucide-react'

import { AlertBanner } from '@/components/alert-banner'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import {
  buildCreateTableDdl,
  defaultColumns,
  toRequestColumns,
  validateSchema,
  type ColumnSpec,
} from '@/lib/schema'

type Props = {
  open: boolean
  onClose: () => void
  onCreate: (
    table: string,
    columns: Record<string, string | boolean>[],
    primaryKey: string | null
  ) => Promise<void>
  onDone: (name: string) => void
}

export function SchemaDesigner({ open, onClose, onCreate, onDone }: Props) {
  const [table, setTable] = useState('')
  const [columns, setColumns] = useState<ColumnSpec[]>(defaultColumns)
  const [primaryKey, setPrimaryKey] = useState<string | null>('id')
  const [serverError, setServerError] = useState<string | null>(null)
  const [saving, setSaving] = useState(false)

  const validation = useMemo(
    () => validateSchema(table, columns, primaryKey),
    [table, columns, primaryKey]
  )
  const preview = useMemo(() => {
    const name = table.trim() || 'my_table'
    return buildCreateTableDdl(name, columns, primaryKey)
  }, [table, columns, primaryKey])

  const reset = useCallback(() => {
    setTable('')
    setColumns(defaultColumns())
    setPrimaryKey('id')
    setServerError(null)
    setSaving(false)
  }, [])

  const update = useCallback((index: number, patch: Partial<ColumnSpec>) => {
    setColumns((prev) =>
      prev.map((col, i) => {
        if (i !== index) return col
        const next = { ...col, ...patch }
        // A renamed primary-key column must stay the primary key, otherwise the
        // selection silently points at a column that no longer exists.
        if (patch.name !== undefined && primaryKey === col.name) {
          setPrimaryKey(patch.name.trim() || null)
        }
        return next
      })
    )
  }, [primaryKey])

  const remove = useCallback(
    (index: number) => {
      setColumns((prev) => {
        const removed = prev[index]
        if (removed && primaryKey === removed.name) setPrimaryKey(null)
        return prev.filter((_, i) => i !== index)
      })
    },
    [primaryKey]
  )

  const move = useCallback((index: number, delta: number) => {
    setColumns((prev) => {
      const target = index + delta
      if (target < 0 || target >= prev.length) return prev
      const next = [...prev]
      const [row] = next.splice(index, 1)
      next.splice(target, 0, row)
      return next
    })
  }, [])

  const submit = async () => {
    if (!validation.ok || saving) return
    setSaving(true)
    setServerError(null)
    try {
      await onCreate(table.trim(), toRequestColumns(columns), primaryKey)
      const created = table.trim()
      reset()
      onDone(created)
    } catch (e) {
      setServerError(e instanceof Error ? e.message : 'Could not create the table.')
      setSaving(false)
    }
  }

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        if (!next && !saving) {
          reset()
          onClose()
        }
      }}
    >
      <DialogContent className="max-w-2xl">
        <DialogHeader>
          <DialogTitle>New table</DialogTitle>
          <DialogDescription>
            Define the columns. This creates the table in the selected project — it does not
            run migrations elsewhere.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5 py-4">
          <div className="space-y-1.5">
            <label htmlFor="schema-table-name" className="block text-sm font-medium text-foreground">
              Table name
            </label>
            <Input
              id="schema-table-name"
              value={table}
              onChange={(e) => setTable(e.target.value)}
              placeholder="notes"
              className="font-mono"
              aria-invalid={validation.tableError ? 'true' : undefined}
              aria-describedby={validation.tableError ? 'schema-table-error' : undefined}
            />
            {validation.tableError && (
              <p id="schema-table-error" role="alert" className="flex items-start gap-1.5 text-xs text-error">
                <AlertCircle className="h-3.5 w-3.5 flex-shrink-0 mt-px" aria-hidden="true" />
                {validation.tableError}
              </p>
            )}
          </div>

          {serverError && (
            <AlertBanner variant="error" message={serverError} onDismiss={() => setServerError(null)} />
          )}

          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-sm font-medium text-foreground">
                Columns
                <span className="ml-2 text-xs font-normal text-muted-foreground">
                  {columns.length}/100
                </span>
              </span>
              <Button
                type="button"
                variant="outline"
                size="sm"
                onClick={() =>
                  setColumns((prev) => [
                    ...prev,
                    { name: '', type: 'TEXT', notNull: false, unique: false, defaultValue: '' },
                  ])
                }
                disabled={columns.length >= 100}
              >
                <Plus className="h-3.5 w-3.5 mr-1" aria-hidden="true" />
                Add column
              </Button>
            </div>

            <ul className="space-y-2">
              {columns.map((col, index) => {
                const error = validation.columnErrors[index]
                const isPk = primaryKey === col.name.trim()
                const errorId = `schema-col-error-${index}`
                return (
                  <li
                    key={index}
                    className={[
                      'border p-3 space-y-3',
                      isPk ? 'border-accent' : 'border-border',
                      error ? 'border-error' : '',
                    ].join(' ')}
                  >
                    <div className="flex items-start gap-2">
                      <div className="flex-1 space-y-1.5">
                        <label
                          htmlFor={`schema-col-name-${index}`}
                          className="sr-only"
                        >
                          Column {index + 1} name
                        </label>
                        <Input
                          id={`schema-col-name-${index}`}
                          value={col.name}
                          onChange={(e) => update(index, { name: e.target.value })}
                          placeholder="column_name"
                          className="font-mono"
                          aria-invalid={error ? 'true' : undefined}
                          aria-describedby={error ? errorId : undefined}
                        />
                      </div>

                      <div className="w-36 flex-shrink-0">
                        <label htmlFor={`schema-col-type-${index}`} className="sr-only">
                          Column {index + 1} type
                        </label>
                        <Select
                          value={col.type}
                          onValueChange={(value) => update(index, { type: value as ColumnSpec['type'] })}
                        >
                          <SelectTrigger id={`schema-col-type-${index}`}>
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {['TEXT', 'INTEGER', 'REAL', 'NUMERIC', 'BOOLEAN', 'DATETIME', 'DATE', 'JSON', 'BLOB'].map(
                              (type) => (
                                <SelectItem key={type} value={type}>
                                  {type}
                                </SelectItem>
                              )
                            )}
                          </SelectContent>
                        </Select>
                      </div>

                      <div className="flex flex-shrink-0 flex-col gap-1">
                        <button
                          type="button"
                          onClick={() => move(index, -1)}
                          disabled={index === 0}
                          className="p-1 text-muted-foreground transition-colors hover:text-foreground disabled:opacity-30 disabled:hover:text-muted-foreground"
                          aria-label={`Move column ${index + 1} up`}
                        >
                          <ArrowUp className="h-4 w-4" aria-hidden="true" />
                        </button>
                        <button
                          type="button"
                          onClick={() => move(index, 1)}
                          disabled={index === columns.length - 1}
                          className="p-1 text-muted-foreground transition-colors hover:text-foreground disabled:opacity-30 disabled:hover:text-muted-foreground"
                          aria-label={`Move column ${index + 1} down`}
                        >
                          <ArrowDown className="h-4 w-4" aria-hidden="true" />
                        </button>
                      </div>

                      <button
                        type="button"
                        onClick={() => remove(index)}
                        disabled={columns.length === 1}
                        className="p-1 text-muted-foreground transition-colors hover:text-error disabled:opacity-30 disabled:hover:text-muted-foreground"
                        aria-label={`Remove column ${col.name || index + 1}`}
                      >
                        <Trash2 className="h-4 w-4" aria-hidden="true" />
                      </button>
                    </div>

                    <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
                      <label className="flex cursor-pointer items-center gap-1.5 text-xs text-foreground">
                        <input
                          type="radio"
                          name="schema-primary-key"
                          checked={isPk}
                          onChange={() => setPrimaryKey(col.name.trim() || null)}
                          className="h-3.5 w-3.5 accent-[var(--pyro-orange)]"
                        />
                        Primary key
                      </label>
                      <label className="flex cursor-pointer items-center gap-1.5 text-xs text-foreground">
                        <input
                          type="checkbox"
                          checked={col.notNull}
                          onChange={(e) => update(index, { notNull: e.target.checked })}
                          className="h-3.5 w-3.5 accent-[var(--pyro-orange)]"
                        />
                        Not null
                      </label>
                      <label className="flex cursor-pointer items-center gap-1.5 text-xs text-foreground">
                        <input
                          type="checkbox"
                          checked={col.unique}
                          onChange={(e) => update(index, { unique: e.target.checked })}
                          className="h-3.5 w-3.5 accent-[var(--pyro-orange)]"
                        />
                        Unique
                      </label>

                      <div className="flex min-w-40 flex-1 items-center gap-1.5">
                        <label
                          htmlFor={`schema-col-default-${index}`}
                          className="text-xs whitespace-nowrap text-muted-foreground"
                        >
                          Default
                        </label>
                        <Input
                          id={`schema-col-default-${index}`}
                          value={col.defaultValue}
                          onChange={(e) => update(index, { defaultValue: e.target.value })}
                          placeholder="optional"
                          className="h-7 font-mono text-xs"
                        />
                      </div>
                    </div>

                    {error && (
                      <p id={errorId} role="alert" className="flex items-start gap-1.5 text-xs text-error">
                        <AlertCircle className="h-3.5 w-3.5 flex-shrink-0 mt-px" aria-hidden="true" />
                        {error}
                      </p>
                    )}
                  </li>
                )
              })}
            </ul>
          </div>

          <div className="space-y-1.5">
            <span className="block text-sm font-medium text-foreground">SQL preview</span>
            <pre
              aria-live="polite"
              className="overflow-x-auto border border-border bg-background p-3 font-mono text-xs leading-relaxed text-muted-foreground"
            >
              {preview}
            </pre>
          </div>
        </div>

        <DialogFooter>
          <Button
            variant="outline"
            onClick={() => {
              reset()
              onClose()
            }}
            disabled={saving}
          >
            Cancel
          </Button>
          <Button onClick={submit} disabled={!validation.ok || saving}>
            {saving ? 'Creating…' : 'Create table'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}